mapper.select:
SELECT * FROM ( SELECT rownum rn, TB.* FROM (

	SELECT IMEMO_NO, SGUBUN, ILAW_ID, SITEM, SDESC, SUSER_ID, SUSER_NAME,
	       SBUSEO_ID, SUBSTR(SINS_DT, 1, 16) AS SINS_DT, SSYS_ID
	  FROM TB_MEMO
	 WHERE SUSER_ID = #{userId}

	   AND SGUBUN = #{vo.searchGubun}


	   AND (UPPER(SDESC) LIKE '%' || UPPER(#{vo.searchKeyword}) || '%'
	    OR  UPPER(SITEM) LIKE '%' || UPPER(#{vo.searchKeyword}) || '%')

	 ORDER BY IMEMO_NO DESC
) TB ) WHERE rn BETWEEN #{vo.firstIndex}+1 AND #{vo.firstIndex}+#{vo.recordCountPerPage}

SELECT COUNT(*) FROM TB_MEMO
 WHERE SUSER_ID = #{userId}

   AND SGUBUN = #{vo.searchGubun}


   AND (UPPER(SDESC) LIKE '%' || UPPER(#{vo.searchKeyword}) || '%'
    OR  UPPER(SITEM) LIKE '%' || UPPER(#{vo.searchKeyword}) || '%')

SELECT IMEMO_NO, SGUBUN, ILAW_ID, SITEM, SDESC, SUSER_ID, SUSER_NAME,
       SBUSEO_ID, SINS_DT, SSYS_ID
  FROM TB_MEMO WHERE IMEMO_NO = #{memoNo}

SELECT IMEMO_NO, SGUBUN, ILAW_ID, SITEM, SDESC, SUSER_ID, SUSER_NAME,
       SBUSEO_ID, SINS_DT, SSYS_ID
  FROM TB_MEMO
 WHERE SUSER_ID = #{userId}
   AND ILAW_ID  = #{lawId}
 ORDER BY SITEM, IMEMO_NO DESC

SELECT IMEMO_NO, SGUBUN, ILAW_ID, SITEM, SDESC, SUSER_ID, SUSER_NAME,
       SBUSEO_ID, SINS_DT, SSYS_ID
  FROM TB_MEMO
 WHERE SUSER_ID = #{userId}
   AND ILAW_ID  = #{lawId}
   AND SITEM    = #{item}
 ORDER BY IMEMO_NO DESC

mapper.update:
UPDATE TB_MEMO SET
	SGUBUN = #{gubun},
	SITEM  = #{item},
	SDESC  = #{contents}
WHERE IMEMO_NO = #{memoNo}
